ST.xhtml:
(* Handshake SMEMA simplificado: 
   Board Available (saída) + Machine Ready (entrada) para envio
   Machine Ready (saída) + Board Available (entrada) para recebimento *)

(* Saída: sinaliza placa disponível se há placa e não estamos em falha *)
xBoardAvailableOut := xPlacaDisponivel AND NOT GVL_Main.xParadaSegura;

(* Saída: sinaliza pronto para receber se estivermos prontos e sem falha *)
xMachineReadyOut := xProntoParaReceber AND NOT GVL_Main.xParadaSegura;

(* Lógica de transferência *)
CASE iState OF
    0: (* Aguardando condições *)
        xTransferenciaOK := FALSE;
        IF xBoardAvailableOut AND xMachineReadyIn THEN
            iState := 10;
            tonTimeout(IN := TRUE, PT := T#5S);
        END_IF;

    10: (* Transferência em andamento - aguarda timeout ou confirmação *)
        IF NOT xBoardAvailableOut THEN
            (* Placa saiu da zona *)
            xTransferenciaOK := TRUE;
            iState := 20;
            tonTimeout(IN := FALSE);
        ELSIF tonTimeout.Q THEN
            (* Timeout de transferência *)
            GVL_Main.udiCodigoAlarme := 1001; (* SMEMA timeout *)
            GVL_Main.xAlarmeAtivo := TRUE;
            iState := 0;
            tonTimeout(IN := FALSE);
        END_IF;

    20: (* Transferência concluída *)
        xTransferenciaOK := TRUE;
        IF NOT xMachineReadyIn THEN
            iState := 0;
        END_IF;
END_CASE;

(* Detecção de inconsistência: ambos os sensores ativos ou nenhum *)
tonInconsistencia(IN := (xSensorRecolhido AND xSensorAvancado) OR 
                        (NOT xSensorRecolhido AND NOT xSensorAvancado),
                  PT := T#500MS);
xErroDuplaConfirma := tonInconsistencia.Q;

IF xErroDuplaConfirma THEN
    GVL_Main.udiCodigoAlarme := 2001;
    GVL_Main.xAlarmeAtivo := TRUE;
END_IF;

(* Atualização de estados *)
xPosicaoAvancada := xSensorAvancado;
xPosicaoRecolhida := xSensorRecolhido;

(* Lógica de controle *)
CASE iState OF
    0: (* Repouso *)
        xValvulaAvancar := FALSE;
        xValvulaRecuar := FALSE;
        xErroTimeout := FALSE;
        tonTimeout(IN := FALSE);

        IF xComandoAvancar AND NOT xSensorAvancado THEN
            iState := 10;
            xValvulaAvancar := TRUE;
            tonTimeout(IN := TRUE, PT := tTimeoutMovimento);
        ELSIF xComandoRecuar AND NOT xSensorRecolhido THEN
            iState := 20;
            xValvulaRecuar := TRUE;
            tonTimeout(IN := TRUE, PT := tTimeoutMovimento);
        END_IF;

    10: (* Avançando *)
        xValvulaAvancar := TRUE;
        IF xSensorAvancado THEN
            xValvulaAvancar := FALSE;
            iState := 0;
            tonTimeout(IN := FALSE);
        ELSIF tonTimeout.Q THEN
            xValvulaAvancar := FALSE;
            xErroTimeout := TRUE;
            GVL_Main.udiCodigoAlarme := 2002;
            GVL_Main.xAlarmeAtivo := TRUE;
            iState := 0;
            tonTimeout(IN := FALSE);
        END_IF;

    20: (* Recuando *)
        xValvulaRecuar := TRUE;
        IF xSensorRecolhido THEN
            xValvulaRecuar := FALSE;
            iState := 0;
            tonTimeout(IN := FALSE);
        ELSIF tonTimeout.Q THEN
            xValvulaRecuar := FALSE;
            xErroTimeout := TRUE;
            GVL_Main.udiCodigoAlarme := 2003;
            GVL_Main.xAlarmeAtivo := TRUE;
            iState := 0;
            tonTimeout(IN := FALSE);
        END_IF;
END_CASE;

CASE iState OF
    0: (* Repouso *)
        xValvulaVacuo := FALSE;
        xPegaConfirmada := FALSE;
        xErroPega := FALSE;
        tonTimeout(IN := FALSE);

        IF xComandoAspirar THEN
            iState := 10;
            xValvulaVacuo := TRUE;
            tonTimeout(IN := TRUE, PT := tTimeoutPega);
        END_IF;

    10: (* Aspirando - aguarda confirmação *)
        xValvulaVacuo := TRUE;

        IF xPressostato THEN
            xPegaConfirmada := TRUE;
            xErroPega := FALSE;
            iState := 20;
            tonTimeout(IN := FALSE);
        ELSIF tonTimeout.Q THEN
            xValvulaVacuo := FALSE;
            xPegaConfirmada := FALSE;
            xErroPega := TRUE;
            GVL_Main.udiCodigoAlarme := 3001;
            GVL_Main.xAlarmeAtivo := TRUE;
            iState := 0;
            tonTimeout(IN := FALSE);
        END_IF;

    20: (* Pega confirmada - aguarda comando de liberar *)
        xValvulaVacuo := TRUE;

        IF xComandoSoprar THEN
            xValvulaVacuo := FALSE;
            xPegaConfirmada := FALSE;
            iState := 30;
        END_IF;

    30: (* Liberando - aguarda pressostato cair *)
        xValvulaVacuo := FALSE;

        IF NOT xPressostato THEN
            iState := 0;
        END_IF;
END_CASE;

(* Wrapper de homing PLCopen *)
fbHome(Axis := xReferencia,
       Execute := xExecute,
       Position := 0.0);

xDone  := fbHome.Done;
xBusy  := fbHome.Busy;
xError := fbHome.Error;
udiErrorID := fbHome.ErrorID;

IF fbHome.Error THEN
    GVL_Main.udiCodigoAlarme := 4001;
    GVL_Main.xAlarmeAtivo := TRUE;
END_IF;

IF xAbsoluto THEN
    fbMoveRel(Axis := xReferencia, Execute := FALSE);
    fbMoveAbs(Axis := xReferencia,
              Execute := xExecute,
              Position := lrPosicao,
              Velocity := lrVelocidade,
              Acceleration := lrAceleracao,
              Deceleration := lrDesaceleracao);
    xDone  := fbMoveAbs.Done;
    xBusy  := fbMoveAbs.Busy;
    xError := fbMoveAbs.Error;
    udiErrorID := fbMoveAbs.ErrorID;
ELSE
    fbMoveAbs(Axis := xReferencia, Execute := FALSE);
    fbMoveRel(Axis := xReferencia,
              Execute := xExecute,
              Distance := lrPosicao,
              Velocity := lrVelocidade,
              Acceleration := lrAceleracao,
              Deceleration := lrDesaceleracao);
    xDone  := fbMoveRel.Done;
    xBusy  := fbMoveRel.Busy;
    xError := fbMoveRel.Error;
    udiErrorID := fbMoveRel.ErrorID;
END_IF;

IF xError THEN
    GVL_Main.udiCodigoAlarme := 4002;
    GVL_Main.xAlarmeAtivo := TRUE;
END_IF;

(* Ciclo pick-and-place:
   1. Mover X,Y,Theta para posição
   2. Descer Z
   3. Aspirar (confirmar pressostato)
   4. Subir Z
   5. Mover para posição de liberação (mesma posição para simplificar)
   6. Descer Z
   7. Liberar vácuo
   8. Subir Z
*)

CASE iState OF
    0: (* Repouso *)
        xCicloCompleto := FALSE;
        xErro := FALSE;
        iEtapa := 0;
        IF xIniciar AND NOT GVL_Main.xParadaSegura THEN
            iState := 10;
        END_IF;

    10: (* Mover X,Y,Theta para posição *)
        iEtapa := 10;
        fbMoveX(xExecute := TRUE, xReferencia := xReferenciaX, 
                lrPosicao := stPosicao.lrX, xAbsoluto := TRUE);
        fbMoveY(xExecute := TRUE, xReferencia := xReferenciaY,
                lrPosicao := stPosicao.lrY, xAbsoluto := TRUE);
        fbMoveTheta(xExecute := TRUE, xReferencia := xReferenciaTheta,
                    lrPosicao := stPosicao.lrTheta, xAbsoluto := TRUE);

        IF fbMoveX.xDone AND fbMoveY.xDone AND fbMoveTheta.xDone THEN
            fbMoveX(xExecute := FALSE, xReferencia := xReferenciaX);
            fbMoveY(xExecute := FALSE, xReferencia := xReferenciaY);
            fbMoveTheta(xExecute := FALSE, xReferencia := xReferenciaTheta);
            iState := 20;
        ELSIF fbMoveX.xError OR fbMoveY.xError OR fbMoveTheta.xError THEN
            xErro := TRUE;
            iState := 0;
        END_IF;

    20: (* Descer Z para pegar *)
        iEtapa := 20;
        fbMoveZ(xExecute := TRUE, xReferencia := xReferenciaZ,
                lrPosicao := stPosicao.lrZ - 10.0, xAbsoluto := TRUE);

        IF fbMoveZ.xDone THEN
            fbMoveZ(xExecute := FALSE, xReferencia := xReferenciaZ);
            iState := 30;
        ELSIF fbMoveZ.xError THEN
            xErro := TRUE;
            iState := 0;
        END_IF;

    30: (* Aspirar componente *)
        iEtapa := 30;
        fbVacuo(xComandoAspirar := TRUE, xPressostato := GVL_Main.xPressostatoVacuo);

        IF fbVacuo.xPegaConfirmada THEN
            iState := 40;
        ELSIF fbVacuo.xErroPega THEN
            xErro := TRUE;
            iState := 0;
        END_IF;

    40: (* Subir Z *)
        iEtapa := 40;
        fbVacuo(xComandoAspirar := TRUE, xPressostato := GVL_Main.xPressostatoVacuo);
        fbMoveZ(xExecute := TRUE, xReferencia := xReferenciaZ,
                lrPosicao := stPosicao.lrZ + 20.0, xAbsoluto := TRUE);

        IF fbMoveZ.xDone THEN
            fbMoveZ(xExecute := FALSE, xReferencia := xReferenciaZ);
            iState := 50;
        ELSIF fbMoveZ.xError THEN
            xErro := TRUE;
            iState := 0;
        END_IF;

    50: (* Mover para posição de liberação - usa mesma posição *)
        iEtapa := 50;
        (* Já está na posição correta para simplificar *)
        iState := 60;

    60: (* Descer Z para liberar *)
        iEtapa := 60;
        fbVacuo(xComandoAspirar := TRUE, xPressostato := GVL_Main.xPressostatoVacuo);
        fbMoveZ(xExecute := TRUE, xReferencia := xReferenciaZ,
                lrPosicao := stPosicao.lrZ - 10.0, xAbsoluto := TRUE);

        IF fbMoveZ.xDone THEN
            fbMoveZ(xExecute := FALSE, xReferencia := xReferenciaZ);
            iState := 70;
        ELSIF fbMoveZ.xError THEN
            xErro := TRUE;
            iState := 0;
        END_IF;

    70: (* Liberar componente *)
        iEtapa := 70;
        fbVacuo(xComandoSoprar := TRUE, xPressostato := GVL_Main.xPressostatoVacuo);

        IF NOT fbVacuo.xPegaConfirmada THEN
            iState := 80;
        END_IF;

    80: (* Subir Z *)
        iEtapa := 80;
        fbMoveZ(xExecute := TRUE, xReferencia := xReferenciaZ,
                lrPosicao := stPosicao.lrZ + 30.0, xAbsoluto := TRUE);

        IF fbMoveZ.xDone THEN
            fbMoveZ(xExecute := FALSE, xReferencia := xReferenciaZ);
            xCicloCompleto := TRUE;
            iState := 0;
        ELSIF fbMoveZ.xError THEN
            xErro := TRUE;
            iState := 0;
        END_IF;
END_CASE;

CASE iState OF
    0: (* Aguardando início *)
        xInspecaoCompleta := FALSE;
        xAprovado := FALSE;
        xRejeitado := FALSE;
        iTentativas := 0;

        IF xIniciarInspecao AND NOT GVL_Main.xParadaSegura THEN
            iState := 10;
            iTentativas := 1;
            tonAtraso(IN := TRUE, PT := T#500MS);
        END_IF;

    10: (* Aguardando resultado da inspeção *)
        IF tonAtraso.Q THEN
            IF xResultadoInspecao THEN
                xAprovado := TRUE;
                xInspecaoCompleta := TRUE;
                iState := 0;
            ELSE
                IF iTentativas < 2 THEN
                    (* Nova tentativa *)
                    iTentativas := iTentativas + 1;
                    tonAtraso(IN := FALSE);
                    tonAtraso(IN := TRUE, PT := T#500MS);
                ELSE
                    (* Falha após 2 tentativas *)
                    xRejeitado := TRUE;
                    xInspecaoCompleta := TRUE;
                    GVL_Main.udiPlacasRejeitadas := GVL_Main.udiPlacasRejeitadas + 1;
                    iState := 0;
                END_IF;
            END_IF;
        END_IF;
END_CASE;

CASE iState OF
    0: (* Aguardando comando *)
        xCarregada := FALSE;
        xErro := FALSE;

        IF xCarregar AND xMaquinaParada THEN
            IF iNovaReceita >= 1 AND iNovaReceita <= 3 THEN
                iReceitaAtiva := iNovaReceita;
                iState := 10;
            ELSE
                xErro := TRUE;
                GVL_Main.udiCodigoAlarme := 5001;
                GVL_Main.xAlarmeAtivo := TRUE;
            END_IF;
        END_IF;

    10: (* Carregando receita *)
           CASE iReceitaAtiva OF
        1:
            GVL_Main.iQtdComponentes := 5;

            GVL_Main.aPosicoes[1].lrX := 100.0; GVL_Main.aPosicoes[1].lrY := 50.0; GVL_Main.aPosicoes[1].lrZ := 0.0; GVL_Main.aPosicoes[1].lrTheta := 0.0;
            GVL_Main.aPosicoes[2].lrX := 150.0; GVL_Main.aPosicoes[2].lrY := 50.0; GVL_Main.aPosicoes[2].lrZ := 0.0; GVL_Main.aPosicoes[2].lrTheta := 0.0;
            GVL_Main.aPosicoes[3].lrX := 200.0; GVL_Main.aPosicoes[3].lrY := 50.0; GVL_Main.aPosicoes[3].lrZ := 0.0; GVL_Main.aPosicoes[3].lrTheta := 0.0;
            GVL_Main.aPosicoes[4].lrX := 100.0; GVL_Main.aPosicoes[4].lrY := 100.0; GVL_Main.aPosicoes[4].lrZ := 0.0; GVL_Main.aPosicoes[4].lrTheta := 90.0;
            GVL_Main.aPosicoes[5].lrX := 150.0; GVL_Main.aPosicoes[5].lrY := 100.0; GVL_Main.aPosicoes[5].lrZ := 0.0; GVL_Main.aPosicoes[5].lrTheta := 90.0;

        2:
            GVL_Main.iQtdComponentes := 3;

            GVL_Main.aPosicoes[1].lrX := 80.0;  GVL_Main.aPosicoes[1].lrY := 60.0; GVL_Main.aPosicoes[1].lrZ := 0.0; GVL_Main.aPosicoes[1].lrTheta := 0.0;
            GVL_Main.aPosicoes[2].lrX := 130.0; GVL_Main.aPosicoes[2].lrY := 80.0; GVL_Main.aPosicoes[2].lrZ := 0.0; GVL_Main.aPosicoes[2].lrTheta := 180.0;
            GVL_Main.aPosicoes[3].lrX := 180.0; GVL_Main.aPosicoes[3].lrY := 60.0; GVL_Main.aPosicoes[3].lrZ := 0.0; GVL_Main.aPosicoes[3].lrTheta := 0.0;

        3:
            GVL_Main.iQtdComponentes := 8;

            GVL_Main.aPosicoes[1].lrX := 60.0;  GVL_Main.aPosicoes[1].lrY := 40.0; GVL_Main.aPosicoes[1].lrZ := 0.0; GVL_Main.aPosicoes[1].lrTheta := 0.0;
            GVL_Main.aPosicoes[2].lrX := 100.0; GVL_Main.aPosicoes[2].lrY := 40.0; GVL_Main.aPosicoes[2].lrZ := 0.0; GVL_Main.aPosicoes[2].lrTheta := 0.0;
            GVL_Main.aPosicoes[3].lrX := 140.0; GVL_Main.aPosicoes[3].lrY := 40.0; GVL_Main.aPosicoes[3].lrZ := 0.0; GVL_Main.aPosicoes[3].lrTheta := 0.0;
            GVL_Main.aPosicoes[4].lrX := 180.0; GVL_Main.aPosicoes[4].lrY := 40.0; GVL_Main.aPosicoes[4].lrZ := 0.0; GVL_Main.aPosicoes[4].lrTheta := 0.0;

            GVL_Main.aPosicoes[5].lrX := 60.0;  GVL_Main.aPosicoes[5].lrY := 80.0; GVL_Main.aPosicoes[5].lrZ := 0.0; GVL_Main.aPosicoes[5].lrTheta := 90.0;
            GVL_Main.aPosicoes[6].lrX := 100.0; GVL_Main.aPosicoes[6].lrY := 80.0; GVL_Main.aPosicoes[6].lrZ := 0.0; GVL_Main.aPosicoes[6].lrTheta := 90.0;
            GVL_Main.aPosicoes[7].lrX := 140.0; GVL_Main.aPosicoes[7].lrY := 80.0; GVL_Main.aPosicoes[7].lrZ := 0.0; GVL_Main.aPosicoes[7].lrTheta := 90.0;
            GVL_Main.aPosicoes[8].lrX := 180.0; GVL_Main.aPosicoes[8].lrY := 80.0; GVL_Main.aPosicoes[8].lrZ := 0.0; GVL_Main.aPosicoes[8].lrTheta := 90.0;
    END_CASE;

        GVL_Main.xReceitaCarregada := TRUE;
        xCarregada := TRUE;
        iState := 20;

    20: (* Receita carregada *)
        IF NOT xCarregar THEN
            iState := 0;
        END_IF;
END_CASE;

(* Alarme pendente = condição de falha presente *)
xAlarmePendente := GVL_Main.xAlarmeAtivo;

(* Alarme ativo = pendente E não reconhecido *)
xAlarmeAtivo := xAlarmePendente AND NOT xAlarmeReconhecido;

(* Reconhecimento *)
IF xReconhecer AND xAlarmePendente THEN
    xAlarmeReconhecido := TRUE;
END_IF;

(* Reset - só permite se condição desapareceu *)
IF xReset AND NOT xAlarmePendente THEN
    xAlarmeReconhecido := FALSE;
    udiCodigoAtivo := 0;
    GVL_Main.udiCodigoAlarme := 0;
    GVL_Main.xAlarmeAtivo := FALSE;
END_IF;

(* Atualiza saídas globais *)
udiCodigoAtivo := GVL_Main.udiCodigoAlarme;
GVL_Main.xAlarmeReconhecido := xAlarmeReconhecido;

(* Detecta mudança no contador de heartbeat *)
IF dwHeartbeatIHM <> dwUltimoValor THEN
    dwUltimoValor := dwHeartbeatIHM;
    tonTimeout(IN := FALSE);
    tonTimeout(IN := TRUE, PT := tTimeout);
    xComOK := TRUE;
    xTimeout := FALSE;
ELSE
    tonTimeout(IN := TRUE, PT := tTimeout);
    IF tonTimeout.Q THEN
        xComOK := FALSE;
        xTimeout := TRUE;
    END_IF;
END_IF;

(* Timeout força parada segura *)
IF xTimeout THEN
    GVL_Main.xParadaSegura := TRUE;
    GVL_Main.udiCodigoAlarme := 6001;
    GVL_Main.xAlarmeAtivo := TRUE;
END_IF;

(* Atualiza GVL *)
GVL_Main.xIHMComOK := xComOK;

(* ============================================ *)
(* 1. VERIFICAÇÕES DE SEGURANÇA - PRIORIDADE MÁXIMA *)
(* ============================================ *)

(* Emergência e porta - sobrepõem qualquer estado *)
IF NOT GVL_Main.xEmergencia OR NOT GVL_Main.xPortaProtecao THEN
    GVL_Main.xParadaSegura := TRUE;
    GVL_Main.udiCodigoAlarme := 9001;
    GVL_Main.xAlarmeAtivo := TRUE;
    iEstadoPrincipal := 999;  (* Estado de falha *)

    (* Desliga todas as saídas *)
    GVL_Main.xMotorEntrada := FALSE;
    GVL_Main.xMotorMontagem := FALSE;
    GVL_Main.xMotorSaida := FALSE;
    GVL_Main.xValvulaCilindro := FALSE;
    GVL_Main.xValvulaVacuo := FALSE;
END_IF;

(* ============================================ *)
(* 2. HEARTBEAT DA IHM *)
(* ============================================ *)
fbHeartbeat(dwHeartbeatIHM := GVL_Main.dwHeartbeatIHM, tTimeout := T#3S);

IF fbHeartbeat.xTimeout THEN
    iEstadoPrincipal := 999;
END_IF;

(* ============================================ *)
(* 3. GESTÃO DE ALARMES *)
(* ============================================ *)
fbAlarme(xReconhecer := GVL_Main.xAlarmeReconhecido,
         xReset := GVL_Main.xResetAlarmes);

IF fbAlarme.xAlarmeAtivo THEN
    iEstadoPrincipal := 999;
END_IF;

(* ============================================ *)
(* 4. MÁQUINA DE ESTADOS PRINCIPAL *)
(* ============================================ *)
CASE iEstadoPrincipal OF
    0: (* INICIALIZAÇÃO *)
        GVL_Main.xCicloAutomatico := FALSE;
        GVL_Main.xHomingConcluido := FALSE;

        (* Habilita eixos *)
        (* (MC_Power deve ser chamado antes - omitido para brevidade) *)

        IF GVL_Main.xReceitaCarregada AND GVL_Main.xIHMComOK 
           AND NOT GVL_Main.xParadaSegura THEN
            xHomingSolicitado := TRUE;
            iEstadoPrincipal := 10;
        END_IF;

    10: (* HOMING DOS EIXOS *)
        fbHomingX(xExecute := xHomingSolicitado, xReferencia := GVL_Main.xAxisX_Ref);
        fbHomingY(xExecute := xHomingSolicitado, xReferencia := GVL_Main.xAxisY_Ref);
        fbHomingZ(xExecute := xHomingSolicitado, xReferencia := GVL_Main.xAxisZ_Ref);
        fbHomingTheta(xExecute := xHomingSolicitado, xReferencia := GVL_Main.xAxisTheta_Ref);

        IF fbHomingX.xDone AND fbHomingY.xDone 
           AND fbHomingZ.xDone AND fbHomingTheta.xDone THEN
            GVL_Main.xHomingConcluido := TRUE;
            xHomingSolicitado := FALSE;
            iEstadoPrincipal := 20;
        ELSIF fbHomingX.xError OR fbHomingY.xError 
              OR fbHomingZ.xError OR fbHomingTheta.xError THEN
            GVL_Main.udiCodigoAlarme := 4003;
            GVL_Main.xAlarmeAtivo := TRUE;
            iEstadoPrincipal := 999;
        END_IF;

    20: (* AGUARDANDO PLACA NA ZONA DE MONTAGEM *)
        GVL_Main.xCicloAutomatico := TRUE;

        fbZonaEntrada(xSensorPlaca := GVL_Main.xSensorEntrada,
                      xHabilitar := TRUE);
        fbZonaMontagem(xSensorPlaca := GVL_Main.xSensorMontagem,
                       xHabilitar := FALSE);  (* Para quando placa presente *)
        fbZonaSaida(xSensorPlaca := GVL_Main.xSensorSaida,
                    xHabilitar := GVL_Main.xSensorSaida);  (* Avança se placa presente *)

        IF GVL_Main.xSensorMontagem THEN
            iComponenteAtual := 1;
            iEstadoPrincipal := 30;
        END_IF;

    30: (* CICLO DE PICK-AND-PLACE *)
        fbPickPlace(xIniciar := TRUE,
                    stPosicao := GVL_Main.aPosicoes[iComponenteAtual],
                    xReferenciaX := GVL_Main.xAxisX_Ref,
                    xReferenciaY := GVL_Main.xAxisY_Ref,
                    xReferenciaZ := GVL_Main.xAxisZ_Ref,
                    xReferenciaTheta := GVL_Main.xAxisTheta_Ref);

        IF fbPickPlace.xCicloCompleto THEN
            iComponenteAtual := iComponenteAtual + 1;
            fbPickPlace(xIniciar := FALSE, 
                        stPosicao := GVL_Main.aPosicoes[1],
                        xReferenciaX := GVL_Main.xAxisX_Ref,
                        xReferenciaY := GVL_Main.xAxisY_Ref,
                        xReferenciaZ := GVL_Main.xAxisZ_Ref,
                        xReferenciaTheta := GVL_Main.xAxisTheta_Ref);

            IF iComponenteAtual > GVL_Main.iQtdComponentes THEN
                iEstadoPrincipal := 40;
            END_IF;
        ELSIF fbPickPlace.xErro THEN
            GVL_Main.udiCodigoAlarme := 7001;
            GVL_Main.xAlarmeAtivo := TRUE;
            iEstadoPrincipal := 999;
        END_IF;

    40: (* INSPEÇÃO AOI *)
        fbAOI(xIniciarInspecao := TRUE,
              xResultadoInspecao := TRUE);  (* Simulado: sempre aprova *)

        IF fbAOI.xInspecaoCompleta THEN
            IF fbAOI.xAprovado THEN
                GVL_Main.udiPlacasProduzidas := GVL_Main.udiPlacasProduzidas + 1;
            END_IF;
            (* Se rejeitado, contador já foi incrementado no FB *)
            iEstadoPrincipal := 50;
        END_IF;

    50: (* TRANSFERIR PLACA PARA SAÍDA *)
        fbZonaMontagem(xSensorPlaca := GVL_Main.xSensorMontagem,
                       xHabilitar := TRUE);  (* Avança para saída *)

        fbSMEMASaida(xBoardAvailableIn := GVL_Main.xSMEMA_BoardAvailIn,
                     xMachineReadyIn := GVL_Main.xSMEMA_MachineReadyIn,
                     xPlacaDisponivel := GVL_Main.xSensorSaida,
                     xProntoParaReceber := NOT GVL_Main.xSensorSaida);

        GVL_Main.xSMEMA_BoardAvailToDownstream := fbSMEMASaida.xBoardAvailableOut;
        GVL_Main.xSMEMA_MachineReadyToUpstream := fbSMEMASaida.xMachineReadyOut;

        IF NOT GVL_Main.xSensorMontagem THEN
            iEstadoPrincipal := 60;
        END_IF;

    60: (* AGUARDAR SAÍDA DA PLACA *)
        IF NOT GVL_Main.xSensorSaida THEN
            (* Placa saiu - reset para próximo ciclo *)
            fbAOI(xIniciarInspecao := FALSE, xResultadoInspecao := FALSE);
            iEstadoPrincipal := 20;
        END_IF;

    999: (* ESTADO DE FALHA *)
        (* Desliga todas as saídas *)
        GVL_Main.xMotorEntrada := FALSE;
        GVL_Main.xMotorMontagem := FALSE;
        GVL_Main.xMotorSaida := FALSE;
        GVL_Main.xValvulaCilindro := FALSE;
        GVL_Main.xValvulaVacuo := FALSE;
        GVL_Main.xCicloAutomatico := FALSE;

        (* Reset *)
        IF GVL_Main.xResetAlarmes AND NOT GVL_Main.xAlarmeAtivo 
           AND NOT GVL_Main.xParadaSegura THEN
            iEstadoPrincipal := 0;
        END_IF;
END_CASE;

(* ============================================ *)
(* 5. ATUALIZAÇÃO DE SAÍDAS FÍSICAS *)
(* ============================================ *)
GVL_Main.xMotorEntrada := fbZonaEntrada.xMotor;
GVL_Main.xMotorMontagem := fbZonaMontagem.xMotor;
GVL_Main.xMotorSaida := fbZonaSaida.xMotor;

(* ============================================ *)
(* 6. GERENCIAMENTO DE RECEITAS (apenas com máquina parada) *)
(* ============================================ *)
fbReceita(iNovaReceita := GVL_Main.iReceitaSelecionada,
          xCarregar := xReceitaSelecionada,
          xMaquinaParada := NOT GVL_Main.xCicloAutomatico);

xReceitaSelecionada := FALSE;  (* Reset após uso *)

(* Debounce do sensor *)
tonDebounce(IN := xSensorPlaca, PT := T#100MS);
xPlacaPresente := tonDebounce.Q;

(* Controle do motor *)
xMotor := xHabilitar AND NOT GVL_Main.xParadaSegura;

(* Diagnóstico simples *)
xErro := FALSE;

IF xHabilitar AND NOT xSensorPlaca AND NOT xMotor THEN
    (* Zona habilitada mas sem placa - estado normal *)
    xErro := FALSE;
END_IF;

(* Nota: sentido e velocidade dependem de hardware específico (VFD ou relé) *)
